const BASE_Y = rulesOf(rowSvg(400, ROW)).base;    // the base rule of a row, from its top
const START_PAD = Math.round((BASE_Y - 0.829 * START_PX) * 10) / 10;   // puts a starter's baseline on the base rule
const BOX = 52;                                   // a box for one letter
const AP = '’';
/** the advance of each letter of Nunito 700 in em (measured 2026-11-17 on a rendered page, canvas measureText) */
const GLYPH_EM = { a: 0.55, b: 0.6, c: 0.47, d: 0.6, e: 0.54, f: 0.36, g: 0.6, h: 0.59, i: 0.26, j: 0.26, k: 0.54, l: 0.32, m: 0.88, n: 0.59, o: 0.58, p: 0.6, q: 0.6, r: 0.39, s: 0.49, t: 0.38, u: 0.58, v: 0.53, w: 0.85, x: 0.55, y: 0.53, z: 0.47, A: 0.74, B: 0.69, C: 0.68, D: 0.76, E: 0.6, F: 0.56, G: 0.74, H: 0.77, I: 0.28, J: 0.35, K: 0.67, L: 0.56, M: 0.87, N: 0.75, O: 0.79, P: 0.65, Q: 0.79, R: 0.69, S: 0.63, T: 0.62, U: 0.74, V: 0.71, W: 1.11, X: 0.67, Y: 0.62, Z: 0.61, "'": 0.25, [AP]: 0.25, ' ': 0.27, '.': 0.27, ',': 0.27, '!': 0.3, '?': 0.5, '“': 0.4, '”': 0.4, '-': 0.36, ':': 0.27 };
const emOf = (s) => [...String(s)].reduce((n, c) => n + (GLYPH_EM[c] || 0.6), 0);
const nCh = (s) => [...String(s)].length;
const capOf = (w) => Math.floor(w / PXCH + 1e-9);
const startW = (t) => (t ? Math.ceil(emOf(t) * START_PX) + 18 : 0);
const endW = (t) => (t ? Math.ceil(emOf(t) * START_PX) + 10 : 0);
/** a text spread word by word over rows of the given capacities (letters): the lines, or null when it does not fit */
function spread(text, caps) {
  const out = caps.map(() => '');
  let i = 0;
  for (const w of String(text).split(' ')) {
    for (;;) {
      if (i >= caps.length) return null;
      const cand = out[i] ? out[i] + ' ' + w : w;
      if (nCh(cand) <= caps[i]) { out[i] = cand; break; }
      if (!out[i]) return null;   // a word longer than an empty row
      i++;
    }
  }
  return out;
}
