const plainOf = (t) => String(t).replace(/\[([^\]]+)\]/g, '$1');
const capsOf = (t) => String(t).replace(/\[([^\]]+)\]/g, (_, w) => capitalize(w));
const namesOf = (t) => [...String(t).matchAll(/\[([^\]]+)\]/g)].map((m) => m[1]);
/** a sentence that opens with a phrase or a word that would want a comma after it (rule 16) */
const OPENING = /^(On|In|At|After|Before|During|Today|Tomorrow|Yesterday|Next|Last|This|Every|When|If|Then|First|Also)\b/;
