const FRAME = { o: ['I think', 'is the best.'], r1: ['One reason is that', '.'], r2: ['Another reason is that', '.'], r2d: ['It is also great because', '.'], c: ['That is why', 'is great.'], r3: ['Also,', '.'] };
const START2 = { o: 'I think', r1: 'One reason is that', r2: 'It is also great because', c: 'That is why' };   // draft, level 2
const PSTART2 = { o: 'I think', r1: 'because', r2: 'also', c: 'That is why' };   // plan, level 2 (notes)
