const QKIND = { 'recess-game': 'play', 'rainy-game': 'play', 'choice-time': 'play', 'playground-spot': 'play',
  subject: 'learn', 'school-time': 'learn', 'read-place': 'read', book: 'read', season: 'season', 'school-day': 'day', 'class-job': 'job' };
/** the questions every Grade 2 room can answer (choice time, class jobs, a classroom library, and rainy-day games inside
 *  are not in every room): each pair of questions holds one of them at least */
const UNIVERSAL = ['recess-game', 'playground-spot', 'subject', 'school-time', 'season', 'school-day', 'read-place'];
/** a frame filled (level 1's grey examples): "I think tag is the best." */
const fillFrame = ([a, b], fill) => `${a} ${fill}${/^[.!?]/.test(b) ? '' : ' '}${b}`;
const frameExamples = (mode, q) => ({ o: fillFrame(FRAME.o, q.pick), r1: fillFrame(FRAME.r1, q.r1), r2: fillFrame(mode === 'plan' ? FRAME.r2 : FRAME.r2d, q.r2), r: fillFrame(FRAME.r1, q.r1), c: fillFrame(FRAME.c, q.pick) });
